/* Diagnostic only: evaluate in fixture, run usual corpus, collect __esc262trace.
   Or call __esc262run() to run only the two checks. Reload to uninstall. */
(function(){
  if(window.__esc262installed) throw new Error('Escape probe already installed');
  window.__esc262installed=true;
  var rows=window.__esc262trace=[], active=null;
  function state(){
    try{ return window.__gx("(function(){return {stale:typeof SAVE_STALE!=='undefined'&&SAVE_STALE,staleCard:!!document.getElementById('stalesave'),fullscreen:typeof FSG!=='undefined'&&FSG.open,quantity:typeof qtyOpen==='function'&&qtyOpen(),padName:typeof PADNAME!=='undefined'&&!!PADNAME,keys:!!(document.getElementById('keysmodal')&&document.getElementById('keysmodal').classList.contains('on')),snip:typeof SNIP!=='undefined'&&SNIP.on,attract:typeof ATT!=='undefined'?{on:ATT.on,pending:ATT.pending,playing:ATT.playing,loading:ATT.loading}:null,editor:typeof TXBOX!=='undefined'&&!!TXBOX,focus:document.activeElement&&document.activeElement.id,modals:Array.prototype.map.call(document.querySelectorAll('.modal.on'),function(m){return m.id;})};})()"); }
    catch(e){ return {probeError:String(e)}; }
  }
  ['stopPropagation','stopImmediatePropagation'].forEach(function(name){
    var original=Event.prototype[name];
    Event.prototype[name]=function(){
      if(active&&this.type==='keydown'&&(this.code==='Escape'||this.key==='Escape'))
        rows.push({check:active,action:name,phase:this.eventPhase,target:this.target&&this.target.id,current:this.currentTarget===window?'window':this.currentTarget===document?'document':this.currentTarget&&this.currentTarget.id,state:state(),stack:String(new Error().stack)});
      return original.apply(this,arguments);
    };
  });
  var dispatch=EventTarget.prototype.dispatchEvent;
  EventTarget.prototype.dispatchEvent=function(e){
    if(!active||e.type!=='keydown'||(e.code!=='Escape'&&e.key!=='Escape')) return dispatch.apply(this,arguments);
    rows.push({check:active,action:'before escape',state:state()});
    try{ return dispatch.apply(this,arguments); }
    finally{ rows.push({check:active,action:'after escape',state:state(),prevented:e.defaultPrevented}); }
  };
  var pair=window.__REGRESS.filter(function(t){return t.v==='10.10'||t.v==='12.99';});
  if(pair.length!==2) throw new Error('Expected both Escape checks');
  pair.forEach(function(t){
    var original=t.run;
    t.run=function(){
      active=t.v; rows.push({check:active,action:'check entry',state:state()});
      try{ var result=original.apply(this,arguments); rows.push({check:active,action:'result',result:result}); return result; }
      catch(e){rows.push({check:active,action:'threw',error:String(e)});throw e;}
      finally{active=null;}
    };
  });
  window.__esc262run=function(){
    window.__runPrep();
    return pair.map(function(t){window.__topClear();return {version:t.v,result:t.run()};});
  };
  return 'installed: run full corpus, or __esc262run(); collect __esc262trace';
})();

var results=window.__esc262run();
